package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Runs after {@link RequireOwnerFields} on {@code POST /api/owners}: normalizes the telephone into
 * E.164 form, replacing the field in place (so {@link BuildOwner} maps the normalized value).
 * <p>
 * Spaces, dashes and brackets are stripped. When the number carries a leading {@code '+'} the
 * country code is kept as given; otherwise country code {@code '+61'} is assumed and a single
 * leading {@code '0'} is dropped from the national digits. The result must have 8 to 15 digits
 * after the {@code '+'}. A number that cannot form a valid E.164 string is rejected with 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String raw = request.getTelephone();
        String stripped = raw == null ? "" : raw.replaceAll("[\\s\\-()]", "");

        String digits;
        if (stripped.startsWith("+")) {
            digits = stripped.substring(1);
        }
        else {
            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
            digits = "61" + national;
        }

        if (!digits.matches("\\d{8,15}")) {
            throw new InvalidTelephoneException(raw);
        }
        request.setTelephone("+" + digits);
    }
}

===== NormalizeOwnerEmail.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Email is optional. When absent (null or blank) this step leaves the request untouched. When
 * present it must be a syntactically valid address; the value is lower-cased in place (so the
 * mapper stores and later steps return the normalized form) and an invalid address is rejected
 * with 400 via {@link InvalidEmailException}.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String raw = request.getEmail();
        if (raw == null || raw.isBlank()) {
            return;
        }
        String email = raw.toLowerCase(Locale.ROOT);
        if (!EMAIL.matcher(email).matches()) {
            throw new InvalidEmailException(raw);
        }
        request.setEmail(email);
    }
}

===== CheckUniqueOwnerTelephone.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs after {@link NormalizeOwnerTelephone} on {@code POST /api/owners}: rejects the request
 * with 409 via {@link DuplicateTelephoneException} when the normalized telephone is already used
 * by any existing owner. Runs before {@link BuildOwner} so no owner is created on conflict.
 */
public class CheckUniqueOwnerTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findByTelephone(telephone)) {
            if (telephone.equals(existing.getTelephone())) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}

===== CheckUniqueOwnerHousehold.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
 * rejects the request with 409 via {@link DuplicateHouseholdException} when another owner already
 * has the same last name and the same address, compared case-insensitively with collapsed
 * whitespace. The check is skipped when the request opts in with {@code sharesHousehold} true,
 * letting several owners share one household.
 */
public class CheckUniqueOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalizeName(request.getLastName());
        String address = OwnerAddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalizeName(existing.getLastName()))
                    && address.equals(OwnerAddressNormalizer.normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
    private static String normalizeName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

===== CheckOwnerCityCapacity.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on conflict):
 * rejects the request with 409 via {@link CityAtCapacityException} when the request's city already
 * contains {@link #MAX_OWNERS_PER_CITY} or more owners, compared case-insensitively with collapsed
 * whitespace.
 */
public class CheckOwnerCityCapacity {

    /** Maximum owners allowed per city; the next create in a full city is rejected. */
    static final int MAX_OWNERS_PER_CITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = normalize(request.getCity());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(normalize(existing.getCity())) && ++count >= MAX_OWNERS_PER_CITY) {
                throw new CityAtCapacityException(request.getCity());
            }
        }
    }

    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

===== CheckDailyOwnerLimit.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on rejection):
 * rejects the request with 429 via {@link DailyOwnerLimitException} when {@link #MAX_OWNERS_PER_DAY}
 * or more owners have already been registered on the current business day (by {@code
 * registrationDate}). Because a weekend registration date rolls forward to the next Monday (see
 * {@link BusinessDay}), the bucket is that adjusted business day, not the raw calendar day.
 */
public class CheckDailyOwnerLimit {

    /** Maximum owners that may be registered in a single day; the next create is rejected. */
    static final int MAX_OWNERS_PER_DAY = 100;

    public void service(OwnerRepository ownerRepository) throws DailyOwnerLimitException {
        LocalDate today = BusinessDay.rollForward(LocalDate.now());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (today.equals(existing.getRegistrationDate()) && ++count >= MAX_OWNERS_PER_DAY) {
                throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
            }
        }
    }
}

