package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        dto.setBulkSignupWarning(DailyOwnerRegistrations.bulkSignupWarning(ownerRepository));
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}

===== OwnerAddressNormalizer.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical address normalization applied whenever an owner is created. The rules are: trim the
 * ends, collapse every run of whitespace to a single space, upper-case, and expand a small set of
 * common street-type abbreviations to their full word ({@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}). The result is what gets stored and returned, and it is the form every
 * address comparison (household duplicate detection and the shared household id) uses, so equal
 * addresses written differently collapse to the same value.
 */
final class OwnerAddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private OwnerAddressNormalizer() {
    }

    /** Normalize an address; a null or whitespace-only value normalizes to the empty string. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}

===== BusinessDay.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

/**
 * Business-day rules for owner registration. A registration date must fall on a business day:
 * when it lands on a Saturday or Sunday it rolls forward to the next Monday. Used both to adjust
 * the effective registration date (see {@link DefaultOwnerRegistrationDate}) and to bucket the
 * daily create-limit (see {@link CheckDailyOwnerLimit}) so both share one definition.
 */
final class BusinessDay {

    private BusinessDay() {
    }

    /** Roll {@code date} forward over Saturday/Sunday to the next Monday; a weekday is unchanged. */
    static LocalDate rollForward(LocalDate date) {
        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
            date = date.plusDays(1);
        }
        return date;
    }
}

===== DailyOwnerRegistrations.java =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Shared accumulation path for the per-business-day owner-registration rules. Counts the owners
 * whose {@code registrationDate} falls on the current business day (weekends roll forward to the
 * next Monday, see {@link BusinessDay}), the same bucket used by both the daily create-limit
 * ({@link CheckDailyOwnerLimit}) and the bulk-signup warning surfaced on {@link org
 * .springframework.samples.petclinic.rest.dto.OwnerDto}.
 */
final class DailyOwnerRegistrations {

    /** Owners beyond this on the current business day trigger the bulk-signup warning. */
    static final int BULK_SIGNUP_THRESHOLD = 80;

    private DailyOwnerRegistrations() {
    }

    /** Number of owners registered on the current business day. */
    static int countToday(OwnerRepository ownerRepository) {
        LocalDate today = BusinessDay.rollForward(LocalDate.now());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (today.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        return count;
    }

    /** True when more than {@link #BULK_SIGNUP_THRESHOLD} owners were created on the current business day. */
    static boolean bulkSignupWarning(OwnerRepository ownerRepository) {
        return countToday(ownerRepository) > BULK_SIGNUP_THRESHOLD;
    }
}

